9		"reflect"
10		"strings"
11		"testing"
12		"unicode/utf8"
13	)
14	
15	// invalidByte is a lone byte that is never valid UTF-8 on its own.
16	const invalidByte = "\xff"
17	
18	// anotherInvalidByte renders identically under JSON replacement but is a
19	// different raw byte.
20	const anotherInvalidByte = "\xfe"
21	
22	// replacementRune is a genuine U+FFFD code point: valid UTF-8, unlike the
23	// lone invalid bytes.
24	const replacementRune = string(rune(0xFFFD))
25	
26	// legacyJSONFingerprint is the exact fingerprint algorithm used before
27	// the raw-content integrity fix: encoding/json over the envelope. Tests
28	// use it to prove valid-UTF-8 records keep byte-identical fingerprints.
29	func legacyJSONFingerprint(r *AuditRecord) string {
30		b, err := json.Marshal(&hashEnvelope{
31			Org:             r.Org,
32			Seq:             r.Seq,
33			Kind:            r.Kind,
34			Change:          r.Change,
35			Decision:        r.Decision,
36			PrevFingerprint: r.PrevFingerprint,
37		})
38		if err != nil {
39			panic(err)
40		}
41		sum := sha256.Sum256(b)
42		return hex.EncodeToString(sum[:])
43	}
44	
45	// cloneExportedRecords deep-copies a record set so mutating any string
46	// field or roles/matched/policies slice in the copy never reaches the
47	// original. encoding/json cannot be used for this: it would "repair" the
48	// invalid bytes under test.
49	func cloneExportedRecords(in []AuditRecord) []AuditRecord {
50		out := make([]AuditRecord, len(in))
51		for i, r := range in {
52			cp := r
53			if r.Change != nil {
54				c := *r.Change
55				if r.Change.Policies != nil {
56					c.Policies = append([]Policy(nil), r.Change.Policies...)
57				}
58				cp.Change = &c
59			}
60			if r.Decision != nil {
61				d := *r.Decision
62				if r.Decision.Request.Subject.Roles != nil {
63					d.Request.Subject.Roles = append([]string(nil), r.Decision.Request.Subject.Roles...)
64				}
65				if r.Decision.Decision.Matched != nil {
66					d.Decision.Matched = append([]string(nil), r.Decision.Decision.Matched...)
67				}
68				cp.Decision = &d
69			}
70			out[i] = cp
71		}
72		return out
73	}
74	
75	// TestInvalidUTF8IsAcceptedAndPreservedByteForByte drives the live API
76	// with strings carrying invalid UTF-8 in every policy and request string
77	// reachable through the public surface. Acceptance must be unchanged, no
78	// byte may be deleted, replaced or normalized, and query/export/offline
79	// review must observe the exact submitted bytes.
80	func TestInvalidUTF8IsAcceptedAndPreservedByteForByte(t *testing.T) {
81		s := NewStore()
82		submitted := Policy{
83			ID:      "策" + invalidByte + "略",
84			Subject: "用" + invalidByte + "戶",
85			Action:  "读" + invalidByte,
86			Scope:   "org/a/资" + invalidByte + "料",
87			Effect:  EffectAllow,
88		}
89		v, err := s.Publish("acme", 0, []Policy{submitted})
90		if err != nil || v != 1 {
91			t.Fatalf("publish with invalid UTF-8 = %d, %v; want accepted", v, err)
92		}
93	
94		req := OrgRequest{
95			SubjectOrg:  "acme",
96			ResourceOrg: "acme",
97			Subject: Subject{
98				ID:    "用" + invalidByte + "戶",
99				Kind:  "外" + invalidByte + "部",
100				Roles: []string{"角" + invalidByte + "色", "普通角色"},
101			},
102			Resource: Resource{ID: "资" + invalidByte + "源", Scope: submitted.Scope},
103			Action:   submitted.Action,
104		}
105		d := s.Decide("acme", req)
106		if !d.Allowed || d.Version != 1 || d.Reason != "matched allow policy" {
107			t.Fatalf("decision on invalid-UTF-8 request = %+v", d)
108		}
109		if want := []string{submitted.ID}; !reflect.DeepEqual(d.Matched, want) {
110			t.Fatalf("matched = %q, want byte-exact %q", d.Matched, want)
111		}
112		if !strings.Contains(d.Matched[0], invalidByte) {
113			t.Fatal("invalid byte normalized out of matched policy id")
114		}
115	
116		// A rollback republishes the invalid-byte content and records it.
117		if rv, err := s.Rollback("acme", 1, 1); err != nil || rv != 2 {
118			t.Fatalf("rollback = %d, %v", rv, err)
119		}
120		// A normal record and an invalid-byte record coexist in one export.
121		if _, err := s.Publish("acme", 2, nil); err != nil {
122			t.Fatal(err)
123		}
124		plain := s.Decide("acme", request("acme", "plain", "r1", "org/a", "read"))
125		if plain.Allowed {
126			t.Fatalf("plain request under empty version must deny: %+v", plain)
127		}
128	
129		recs, cp, err := s.AuditExport("acme", 0)
130		if err != nil {
