145		}
146		if !reflect.DeepEqual(recs[1].Decision.Decision, d) {
147			t.Fatalf("decision bytes = %+v, want %+v", recs[1].Decision.Decision, d)
148		}
149		if !reflect.DeepEqual(recs[2].Change.Policies, []Policy{submitted}) {
150			t.Fatal("rollback record lost the published raw bytes")
151		}
152		for _, haystack := range []string{
153			gotPolicy.ID, gotPolicy.Subject, gotPolicy.Action, gotPolicy.Scope,
154			gotReq.Subject.ID, gotReq.Subject.Kind, gotReq.Subject.Roles[0],
155			gotReq.Resource.ID, gotReq.Resource.Scope, gotReq.Action,
156		} {
157			if !strings.Contains(haystack, invalidByte) {
158				t.Fatalf("invalid byte was deleted or normalized in %q", haystack)
159			}
160		}
161	
162		// Paged queries return the same bytes.
163		page, err := s.AuditQuery("acme", 1, 1, "", "")
164		if err != nil {
165			t.Fatal(err)
166		}
167		queried := append([]AuditRecord(nil), page.Records...)
168		for page.Next != 0 {
169			page, err = s.AuditPage(page.Checkpoint, page.Next, 1, "", "")
170			if err != nil {
171				t.Fatal(err)
172			}
173			queried = append(queried, page.Records...)
174		}
175		if !reflect.DeepEqual(queried, recs) {
176			t.Fatal("paged query bytes differ from the export bytes")
177		}
178	
179		// Offline review recomputes from the raw request and recorded version.
180		review, err := RecheckDecisionOffline("acme", recs, cp, 2)
181		if err != nil {
182			t.Fatalf("offline review: %v", err)
183		}
184		if !review.Consistent || !reflect.DeepEqual(review.Original, d) ||
185			!reflect.DeepEqual(review.Recomputed, d) {
186			t.Fatalf("offline review = %+v, want consistent with %+v", review, d)
187		}
188		if !strings.Contains(review.Recomputed.Matched[0], invalidByte) {
189			t.Fatal("offline review normalized the matched policy id")
190		}
191	
192		// An organization whose name itself carries invalid bytes: genesis
193		// checkpoint, isolation and offline review all still work.
194		weirdOrg := "组" + invalidByte + "织"
195		if _, err := s.Publish(weirdOrg, 0, []Policy{submitted}); err != nil {
196			t.Fatalf("publish into invalid-UTF-8 org: %v", err)
197		}
198		wreq := req
199		wreq.SubjectOrg = weirdOrg
200		wreq.ResourceOrg = weirdOrg
201		if d := s.Decide(weirdOrg, wreq); !d.Allowed {
202			t.Fatalf("decision inside invalid-UTF-8 org = %+v", d)
203		}
204		wrecs, wcp, err := s.AuditExport(weirdOrg, 0)
205		if err != nil {
206			t.Fatal(err)
207		}
208		if err := VerifyAudit(weirdOrg, wrecs, wcp); err != nil {
209			t.Fatalf("invalid-UTF-8 org chain: %v", err)
210		}
211		if wr, err := RecheckDecisionOffline(weirdOrg, wrecs, wcp, 2); err != nil || !wr.Consistent {
212			t.Fatalf("invalid-UTF-8 org offline review = %+v, %v", wr, err)
213		}
214		// The sequence-0 root checkpoint is the genesis for that org too.
215		empty, emptyCP, err := s.AuditExport(weirdOrg+"-none", 0)
216		if err != nil {
217			t.Fatal(err)
218		}
219		if err := VerifyAudit(weirdOrg+"-none", empty, emptyCP); err != nil {
