223	
224	// TestInvalidBytesFingerprintBuildsChainOfMixedRecords checks ordinary
225	// and invalid-byte records chaining together: ordinary records keep the
226	// legacy JSON fingerprint, the invalid-byte record verifies and is pinned
227	// by the checkpoint, and tampering either family fails with
228	// ErrInvalidRange.
229	func TestInvalidBytesFingerprintBuildsChainOfMixedRecords(t *testing.T) {
230		s := NewStore()
231		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
232		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
233		s.Publish("acme", 1, []Policy{{
234			ID:      "策" + invalidByte + "略",
235			Subject: "用" + invalidByte + "戶",
236			Action:  "read",
237			Scope:   "org/a",
238			Effect:  EffectAllow,
239		}})
240		recs, cp, err := s.AuditExport("acme", 0)
241		if err != nil {
242			t.Fatal(err)
243		}
244		if err := VerifyAudit("acme", recs, cp); err != nil {
245			t.Fatalf("mixed chain: %v", err)
246		}
247		if got := fingerprintFor(&recs[0]); got != legacyJSONFingerprint(&recs[0]) {
248			t.Fatal("valid-UTF-8 record changed fingerprint family")
249		}
250		if got := fingerprintFor(&recs[1]); got != legacyJSONFingerprint(&recs[1]) {
251			t.Fatal("valid-UTF-8 decision changed fingerprint family")
252		}
253		if got := fingerprintFor(&recs[2]); got == legacyJSONFingerprint(&recs[2]) {
254			t.Fatal("invalid-byte record still uses the JSON fingerprint")
255		}
256		if recs[2].Fingerprint != cp.Fingerprint {
257			t.Fatal("checkpoint does not pin the raw-encoded final record")
258		}
259		bad := cloneExportedRecords(recs)
260		bad[2].Change.Policies[0].ID = strings.Replace(bad[2].Change.Policies[0].ID, invalidByte, anotherInvalidByte, 1)
261		if err := VerifyAudit("acme", bad, cp); !errors.Is(err, ErrInvalidRange) {
262			t.Fatalf("tampered invalid-byte record err = %v, want ErrInvalidRange", err)
263		}
