265		bad[0].Change.Policies[0].ID = "p2"
266		if err := VerifyAudit("acme", bad, cp); !errors.Is(err, ErrInvalidRange) {
267			t.Fatalf("tampered ordinary record err = %v, want ErrInvalidRange", err)
268		}
269	}
270	
271	// buildInvalidByteChain constructs a chain where every fingerprinted
272	// string field can be probed. Record 1 is a policy change, record 2 the
273	// reviewed decision with an invalid byte embedded between legal Chinese
274	// in every nested field and list, record 3 a decision after the target.
275	func buildInvalidByteChain(t *testing.T) (string, []AuditRecord, Checkpoint) {
276		t.Helper()
277		org := "组" + invalidByte + "织"
278		subjectID := "身" + invalidByte + "份"
279		action := "动" + invalidByte + "作"
280		scope := "范" + invalidByte + "围"
281		p1 := Policy{
282			ID:      "策" + invalidByte + "id",
283			Subject: subjectID,
284			Action:  action,
285			Scope:   scope,
286			Effect:  EffectAllow,
287		}
288		p2 := Policy{
289			ID:      "命" + invalidByte + "中二",
290			Subject: subjectID,
291			Action:  action,
292			Scope:   scope,
293			Effect:  EffectAllow,
294		}
295		prev := genesisFingerprint(org)
296		rec1 := syntheticRecord(org, 1, AuditPolicyChange, &PolicyChange{
297			Version: 1, Policies: []Policy{p1, p2},
298		}, nil, prev)
299		prev = rec1.Fingerprint
300		rec2 := syntheticRecord(org, 2, AuditDecision, nil, &DecisionRecord{
301			Request: OrgRequest{
302				SubjectOrg:  org,
303				ResourceOrg: org,
304				Subject: Subject{
305					ID:    subjectID, // invalid byte between legal Chinese
306					Kind:  "类" + invalidByte + "型",
307					Roles: []string{"角" + invalidByte + "色", "正常角色"},
308				},
309				Resource: Resource{ID: "资" + invalidByte + "源", Scope: scope},
310				Action:   action,
311			},
312			Decision: Decision{
313				Allowed: true,
314				Reason:  "理" + invalidByte + "由",
315				Matched: []string{p2.ID, p1.ID}, // sorted by raw bytes
316				Version: 1,
317			},
318		}, prev)
319		prev = rec2.Fingerprint
320		rec3 := syntheticRecord(org, 3, AuditDecision, nil, &DecisionRecord{
321			Request: OrgRequest{
322				SubjectOrg:  org,
323				ResourceOrg: org,
324				Subject:     Subject{ID: "尾" + invalidByte + "随"},
325				Resource:    Resource{ID: "later", Scope: "org/a"},
326				Action:      "read",
327			},
328			Decision: Decision{Allowed: false, Reason: "no matching allow policy", Version: 1},
329		}, prev)
