338	// TestTamperedInvalidBytesRejectedEverywhere replaces the lone 0xFF in
339	// every protected field with either 0xFE (the same display after JSON
340	// replacement) or a genuine U+FFFD. VerifyAudit must fail with
341	// ErrInvalidRange and offline review must refuse before returning any
342	// conclusion, including when the damage is after the target decision.
343	func TestTamperedInvalidBytesRejectedEverywhere(t *testing.T) {
344		org, good, cp := buildInvalidByteChain(t)
345	
346		// Document the root cause: JSON renders both raw bytes identically.
347		j1, _ := json.Marshal("身" + invalidByte + "份")
348		j2, _ := json.Marshal("身" + anotherInvalidByte + "份")
349		if !bytes.Equal(j1, j2) {
350			t.Fatalf("test premise broken: JSON differs: %s vs %s", j1, j2)
351		}
352	
353		mutators := []struct {
354			name string
355			fn   func([]AuditRecord, string)
356		}{
357			{"header org", func(r []AuditRecord, repl string) {
358				r[0].Org = strings.Replace(r[0].Org, invalidByte, repl, 1)
359			}},
360			{"record kind", func(r []AuditRecord, repl string) {
361				r[1].Kind += repl
362			}},
363			{"policy id", func(r []AuditRecord, repl string) {
364				p := &r[0].Change.Policies[0]
365				p.ID = strings.Replace(p.ID, invalidByte, repl, 1)
366			}},
367			{"policy subject", func(r []AuditRecord, repl string) {
368				p := &r[0].Change.Policies[0]
369				p.Subject = strings.Replace(p.Subject, invalidByte, repl, 1)
370			}},
371			{"policy action", func(r []AuditRecord, repl string) {
372				p := &r[0].Change.Policies[0]
373				p.Action = strings.Replace(p.Action, invalidByte, repl, 1)
374			}},
375			{"policy scope", func(r []AuditRecord, repl string) {
376				p := &r[0].Change.Policies[0]
377				p.Scope = strings.Replace(p.Scope, invalidByte, repl, 1)
378			}},
379			{"policy effect", func(r []AuditRecord, repl string) {
380				p := &r[0].Change.Policies[0]
381				p.Effect = Effect(string(p.Effect) + repl)
382			}},
383			{"second policy in list", func(r []AuditRecord, repl string) {
384				p := &r[0].Change.Policies[1]
385				p.ID = strings.Replace(p.ID, invalidByte, repl, 1)
386			}},
387			{"subject org", func(r []AuditRecord, repl string) {
388				r[1].Decision.Request.SubjectOrg = strings.Replace(r[1].Decision.Request.SubjectOrg, invalidByte, repl, 1)
389			}},
390			{"resource org", func(r []AuditRecord, repl string) {
391				r[1].Decision.Request.ResourceOrg = strings.Replace(r[1].Decision.Request.ResourceOrg, invalidByte, repl, 1)
392			}},
393			{"subject id between chinese", func(r []AuditRecord, repl string) {
394				id := &r[1].Decision.Request.Subject.ID
395				*id = strings.Replace(*id, invalidByte, repl, 1)
396			}},
397			{"subject kind", func(r []AuditRecord, repl string) {
398				r[1].Decision.Request.Subject.Kind = strings.Replace(r[1].Decision.Request.Subject.Kind, invalidByte, repl, 1)
399			}},
