412			}},
413			{"request action", func(r []AuditRecord, repl string) {
414				r[1].Decision.Request.Action = strings.Replace(r[1].Decision.Request.Action, invalidByte, repl, 1)
415			}},
416			{"decision reason", func(r []AuditRecord, repl string) {
417				r[1].Decision.Decision.Reason = strings.Replace(r[1].Decision.Decision.Reason, invalidByte, repl, 1)
418			}},
419			{"first matched policy", func(r []AuditRecord, repl string) {
420				m := r[1].Decision.Decision.Matched
421				m[0] = strings.Replace(m[0], invalidByte, repl, 1)
422			}},
423			{"second matched policy", func(r []AuditRecord, repl string) {
424				m := r[1].Decision.Decision.Matched
425				m[1] = strings.Replace(m[1], invalidByte, repl, 1)
426			}},
427			{"record after target", func(r []AuditRecord, repl string) {
428				id := &r[2].Decision.Request.Subject.ID
429				*id = strings.Replace(*id, invalidByte, repl, 1)
430			}},
431		}
432	
433		for _, repl := range []string{anotherInvalidByte, replacementRune} {
434			for _, m := range mutators {
435				recs := cloneExportedRecords(good)
436				m.fn(recs, repl)
437				name := m.name + "/repl=" + replacementLabel(repl)
438				if err := VerifyAudit(org, recs, cp); !errors.Is(err, ErrInvalidRange) {
439					t.Fatalf("%s: VerifyAudit err = %v, want ErrInvalidRange", name, err)
440				}
441				// Offline review must reject first: never a successful or
442				// "consistent" conclusion over tampered material.
443				if got, err := RecheckDecisionOffline(org, recs, cp, 2); !errors.Is(err, ErrInvalidRange) {
444					t.Fatalf("%s: RecheckDecisionOffline err = %v, review = %+v, want ErrInvalidRange", name, err, got)
445				}
446			}
447		}
448	}
449	
450	// replacementLabel names a substitution without relying on rendered
451	// output, which displays both cases as a replacement character.
452	func replacementLabel(s string) string {
453		switch s {
454		case anotherInvalidByte:
455			return "0xFE"
456		case replacementRune:
457			return "U+FFFD"
458		default:
459			return "?"
460		}
461	}
462	
463	// TestReplacementRuneIsGenuineContentToo separates three byte-different
464	// strings that displays may conflate: a lone 0xFF, a lone 0xFE, and a
465	// real U+FFFD rune. A record genuinely containing U+FFFD is valid UTF-8,
466	// verifies and keeps the legacy fingerprint; substituting any one for
467	// another is a content change.
468	func TestReplacementRuneIsGenuineContentToo(t *testing.T) {
469		s := NewStore()
470		policies := []Policy{{
471			ID:      "p-" + replacementRune + "-1",
472			Subject: "用" + replacementRune + "戶",
473			Action:  "read", Scope: "org/a", Effect: EffectAllow,
474		}}
475		s.Publish("acme", 0, policies)
476		req := request("acme", "用"+replacementRune+"戶", "r1", "org/a", "read")
477		d := s.Decide("acme", req)
478		if !d.Allowed {
479			t.Fatalf("request with genuine U+FFFD = %+v", d)
480		}
481		recs, cp, err := s.AuditExport("acme", 0)
482		if err != nil {
483			t.Fatal(err)
484		}
485		if err := VerifyAudit("acme", recs, cp); err != nil {
486			t.Fatalf("genuine U+FFFD must verify: %v", err)
487		}
488		if !utf8.ValidString(recs[0].Change.Policies[0].ID) {
489			t.Fatal("genuine U+FFFD must remain valid UTF-8")
490		}
491		if fingerprintFor(&recs[0]) != legacyJSONFingerprint(&recs[0]) {
492			t.Fatal("valid-UTF-8 U+FFFD record must keep the legacy JSON fingerprint")
493		}
494		if review, err := RecheckDecisionOffline("acme", recs, cp, 2); err != nil || !review.Consistent {
495			t.Fatalf("genuine U+FFFD review = %+v, %v", review, err)
496		}
497	
498		// Raw invalid bytes exported from the live API.
499		raw := NewStore()
500		raw.Publish("acme", 0, []Policy{{
501			ID: "p" + invalidByte, Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow,
502		}})
503		rawRecs, rawCP, err := raw.AuditExport("acme", 0)
504		if err != nil {
505			t.Fatal(err)
506		}
507		if err := VerifyAudit("acme", rawRecs, rawCP); err != nil {
508			t.Fatalf("raw-byte record must verify: %v", err)
509		}
510	
511		// Replace the raw byte with a genuine U+FFFD rune: content changed.
512		tampered := cloneExportedRecords(rawRecs)
513		tampered[0].Change.Policies[0].ID = "p" + replacementRune
514		if err := VerifyAudit("acme", tampered, rawCP); !errors.Is(err, ErrInvalidRange) {
515			t.Fatalf("raw 0xFF -> U+FFFD err = %v, want ErrInvalidRange", err)
516		}
517	
518		// The reverse substitution is also a change: the valid-UTF-8 record's
519		// real U+FFFD replaced by a lone 0xFF.
520		back := cloneExportedRecords(recs)
521		back[0].Change.Policies[0].ID = "p-" + invalidByte + "-1"
522		if err := VerifyAudit("acme", back, cp); !errors.Is(err, ErrInvalidRange) {
523			t.Fatalf("U+FFFD -> raw 0xFF err = %v, want ErrInvalidRange", err)
524		}
525	}
526	
527	// TestLegacyFingerprintsUnchangedForValidUTF8 proves byte-identical
528	// fingerprints for valid UTF-8 across policy changes, rollbacks,
529	// decisions, nil-vs-empty lists, and strings full of characters JSON
530	// escapes specially: Chinese, quotes, backslashes, control characters,
531	// angle/ampersand and a genuine replacement rune.
532	func TestLegacyFingerprintsUnchangedForValidUTF8(t *testing.T) {
533		org := "acme"
534		tricky := []Policy{{
535			ID:        "p\"1\\中\t\n\r<>&" + replacementRune,
536			Subject:   "主\"体\\",
537			Action:    "a\tb\nc",
538			Scope:     "org/中/区",
539			Effect:    EffectAllow,
540			Recursive: true,
541		}}
542		prev := genesisFingerprint(org)
543		records := []AuditRecord{
544			syntheticRecord(org, 1, AuditPolicyChange, &PolicyChange{
545				Version: 1, Policies: tricky,
546			}, nil, prev),
547		}
548		prev = records[0].Fingerprint
549		// Rollback carrying a nil policy set.
550		records = append(records, syntheticRecord(org, 2, AuditPolicyChange, &PolicyChange{
551			Version: 2, Policies: nil, SourceVersion: 1, RolledBack: true,
552		}, nil, prev))
553		prev = records[1].Fingerprint
554		// Decision with nil roles and nil matched lists.
555		records = append(records, syntheticRecord(org, 3, AuditDecision, nil, &DecisionRecord{
556			Request: OrgRequest{
557				SubjectOrg:  org,
558				ResourceOrg: org,
559				Subject:     Subject{ID: "身\"份\\中"},
560				Resource:    Resource{ID: "r\"1", Scope: "org/中/区"},
561				Action:      "a\tb",
562			},
563			Decision: Decision{Allowed: true, Reason: "理\"由\n中", Version: 2},
564		}, prev))
565		prev = records[2].Fingerprint
566		// Decision with explicitly empty (non-nil) lists.
567		records = append(records, syntheticRecord(org, 4, AuditDecision, nil, &DecisionRecord{
568			Request: OrgRequest{
569				SubjectOrg:  org,
570				ResourceOrg: org,
571				Subject:     Subject{ID: "u2", Roles: []string{}},
572				Resource:    Resource{ID: "r2", Scope: "org/a"},
573				Action:      "read",
574			},
575			Decision: Decision{Allowed: false, Reason: "no matching allow policy", Matched: []string{}, Version: 2},
576		}, prev))
577	
578		for i := range records {
579			r := &records[i]
580			if got := fingerprintFor(r); got != legacyJSONFingerprint(r) {
581				t.Fatalf("record %d fingerprint drifted from the legacy JSON encoding", r.Seq)
582			}
583		}
584		cp := Checkpoint{Org: org, EndSeq: len(records), Fingerprint: records[len(records)-1].Fingerprint}
585		if err := VerifyAudit(org, records, cp); err != nil {
586			t.Fatalf("legacy-compatible chain must verify: %v", err)
587		}
588	
589		// Sanity: an invalid byte makes the same shape leave the JSON family.
590		raw := syntheticRecord(org, 5, AuditDecision, nil, &DecisionRecord{
591			Request:  request(org, "u"+invalidByte, "r1", "org/a", "read"),
592			Decision: Decision{Allowed: false, Reason: "x", Version: 2},
593		}, cp.Fingerprint)
594		if fingerprintFor(&raw) == legacyJSONFingerprint(&raw) {
595			t.Fatal("invalid-byte envelope unexpectedly shares the JSON fingerprint")
596		}
597	}
