276		u2 := drainAudit(t, s, "acme", AuditDecision, "u2")
277		if len(u2) != 1 || u2[0].Seq != 3 {
278			t.Fatalf("u2 records = %+v, want seq 3", u2)
279		}
280		if none := drainAudit(t, s, "acme", "", "ghost"); len(none) != 0 {
281			t.Fatalf("unknown subject = %+v, want empty", none)
282		}
283	
284		// Ascending order across pages, page size 2.
285		page, err := s.AuditQuery("acme", 1, 2, "", "")
286		if err != nil {
287			t.Fatal(err)
288		}
289		cp := page.Checkpoint
290		var seqs []int
291		seqs = append(seqs, page.Records[0].Seq, page.Records[1].Seq)
292		for page.Next != 0 {
293			page, err = s.AuditPage(cp, page.Next, 2, "", "")
294			if err != nil {
295				t.Fatal(err)
296			}
297			for _, r := range page.Records {
298				seqs = append(seqs, r.Seq)
299			}
300		}
301		if !reflect.DeepEqual(seqs, []int{1, 2, 3, 4, 5}) {
302			t.Fatalf("paged seqs = %v, want 1..5", seqs)
303		}
304	}
